import axios from "axios";
import MaterialTable, { MTableToolbar } from "material-table";
import React, { Component } from "react";
import { connect } from "react-redux";
import { Spinner } from "reactstrap";
import { tokenConfig } from "../../actions/authActions";
import store from "../../store";
import { changePage } from "../../actions/pageActions";
import {
  Checkbox,
  Snackbar,
  MuiAlert,
  Paper,
  Tab,
  Tabs,
  Box
} from "@material-ui/core";
import Typography from "@material-ui/core/Typography";

class ClientDetail extends Component {
  state = {
    value: ""
  };
  handleChange = (event, newValue) => {
    this.setState({ value: newValue });
  };

  render() {
    const TabPanel = props => {
      const { children, value, index, ...other } = props;

      return (
        <div
          role="tabpanel"
          hidden={value !== index}
          id={`vertical-tabpanel-${index}`}
          aria-labelledby={`vertical-tab-${index}`}
          {...other}
        >
          {value === index && (
            <Box p={3}>
              <Typography>{children}</Typography>
            </Box>
          )}
        </div>
      );
    };
    function a11yProps(index) {
      return {
        id: `vertical-tab-${index}`,
        "aria-controls": `vertical-tabpanel-${index}`
      };
    }
    return (
      <Paper square>
        <Tabs
          value={this.state.value}
          orientation="vertical"
          indicatorColor="primary"
          textColor="primary"
          onChange={this.handleChange}
          centered
        >
          <Tab label="Billing" {...a11yProps(0)} />
          <Tab label="Service Agreements" {...a11yProps(1)} />
          <Tab label="Warranty" {...a11yProps(2)} />
          <Tab label="Reports" {...a11yProps(3)} />
          <Tab label="EU Features" {...a11yProps(4)} />
          <Tab label="Service Agreements" {...a11yProps(5)} />
          <Tab label="Requirements Documents" {...a11yProps(6)} />
        </Tabs>

        <TabPanel value={this.value} index={0}>
          Item One
        </TabPanel>
        <TabPanel value={this.value} index={1}>
          Item Two
        </TabPanel>
        <TabPanel value={this.value} index={2}>
          Item Three
        </TabPanel>
        <TabPanel value={this.value} index={3}>
          Item Four
        </TabPanel>
        <TabPanel value={this.value} index={4}>
          Item Five
        </TabPanel>
        <TabPanel value={this.value} index={5}>
          Item Six
        </TabPanel>
        <TabPanel value={this.value} index={6}>
          Item Seven
        </TabPanel>
      </Paper>
    );
  }
}

const mapStateToProps = state => ({
  auth: state.auth
});

export default connect(mapStateToProps, { changePage })(ClientDetail);
